#[cfg(test)]
mod tests {
    use super::*;
    fn setup() -> (tempfile::TempDir, Store, MiningService, PathBuf, i64) {
        let d = tempfile::tempdir().unwrap();
        let root = d.path().join("logs");
        fs::create_dir_all(root.join("Gamelogs")).unwrap();
        let store = Store::open(&d.path().join("state.db")).unwrap();
        let now = chrono::Utc::now().timestamp();
        let service = MiningService::restore(&store, vec![root.clone()], now).unwrap();
        (d, store, service, root, now)
    }
    fn write_log(root: &Path, id: u64, start: i64, events: &[(i64, bool, i64)]) -> PathBuf {
        let ores = events
            .iter()
            .map(|(at, bonus, n)| (*at, *bonus, *n, "Pyroxeres III-Grade"))
            .collect::<Vec<_>>();
        write_ore_log(root, id, start, &ores)
    }
    fn write_ore_log(
        root: &Path,
        id: u64,
        start: i64,
        events: &[(i64, bool, i64, &str)],
    ) -> PathBuf {
        let stamp = |at| {
            chrono::DateTime::from_timestamp(at, 0)
                .unwrap()
                .format("%Y.%m.%d %H:%M:%S")
                .to_string()
        };
        let mut text = format!(
            "------------------------------------------------------------\n  Gamelog\n  Listener: Pilot {id}\n  Session Started: {}\n------------------------------------------------------------\n",
            stamp(start)
        );
        for (at, bonus, n, ore) in events {
            text += &format!(
                "[ {} ] (mining) {}{n} units of {ore}\n",
                stamp(*at),
                if *bonus {
                    "Critical mining success! You mined an additional "
                } else {
                    "You mined "
                }
            );
        }
        let p = root.join(format!("Gamelogs/20260915_120000_{id}.txt"));
        fs::write(&p, text).unwrap();
        p
    }
    #[test]
    fn real_volume_lookup_duplicate_lines_replay_and_preferences() {
        let (_d, store, mut service, root, now) = setup();
        service
            .command(&store, Command::Start { label: None }, now)
            .unwrap();
        let path = write_log(
            &root,
            42,
            now + 1,
            &[
                (now + 2, false, 89),
                (now + 2, false, 89),
                (now + 2, true, 199),
            ],
        );
        service.poll(&store, now + 3).unwrap();
        let view = service.view(&store, now + 61).unwrap();
        let s = view.session.unwrap();
        assert!((s.totals.total_m3 - 113.1).abs() < 1e-9);
        assert_eq!(s.totals.crits, 1);
        assert!((s.totals.recent_rate - 113.1 / 60.0).abs() < 1e-9);
        let mut resumed = MiningService::restore(&store, vec![root], now + 62).unwrap();
        resumed.poll(&store, now + 62).unwrap();
        assert_eq!(
            resumed
                .view(&store, now + 62)
                .unwrap()
                .session
                .unwrap()
                .totals
                .total_m3,
            s.totals.total_m3
        );
        // Rolling output decays without needing another log line.
        assert_eq!(
            resumed
                .view(&store, now + 100)
                .unwrap()
                .session
                .unwrap()
                .totals
                .recent_rate,
            0.0
        );
        let mut prefs = resumed.preferences.clone();
        prefs.window_seconds = 0;
        assert!(
            resumed
                .command(
                    &store,
                    Command::Preferences {
                        value: Box::new(prefs)
                    },
                    now + 100
                )
                .is_err()
        );
        assert_eq!(resumed.preferences.window_seconds, 60);
        // A new generation at the same path counts independently, even for equal messages.
        let old = path.with_extension("old");
        fs::rename(&path, old).unwrap();
        write_log(
            path.parent().unwrap().parent().unwrap(),
            42,
            now + 101,
            &[(now + 102, false, 89)],
        );
        resumed.poll(&store, now + 103).unwrap();
        assert!(
            (resumed
                .view(&store, now + 103)
                .unwrap()
                .session
                .unwrap()
                .totals
                .total_m3
                - 139.8)
                .abs()
                < 1e-9
        );
    }
    #[test]
    fn shared_denominator_late_join_and_stop_boundary() {
        let (_d, store, mut service, root, now) = setup();
        service
            .command(&store, Command::Start { label: None }, now)
            .unwrap();
        write_log(&root, 1, now + 1, &[(now + 2, false, 2000)]);
        write_log(&root, 2, now + 1, &[(now + 45, false, 1000)]);
        service.poll(&store, now + 60).unwrap();
        let s = service.view(&store, now + 60).unwrap().session.unwrap();
        assert_eq!(s.totals.recent_rate, 15.0);
        assert_eq!(
            s.pilots.iter().map(|p| p.totals.recent_rate).sum::<f64>(),
            15.0
        );
        service.command(&store, Command::Stop, now + 60).unwrap();
        assert_eq!(
            session_for(store.connection(), now + 61, "1").unwrap(),
            None
        );
        assert!(
            session_for(store.connection(), now + 60, "1")
                .unwrap()
                .is_some()
        );
    }

    #[test]
    fn a_gamelog_from_character_select_is_skipped_without_complaint() {
        let (_d, store, mut service, root, now) = setup();
        let stamp = chrono::DateTime::from_timestamp(now, 0)
            .unwrap()
            .format("%Y.%m.%d %H:%M:%S");
        // EVE writes this every time the client reaches character select. The
        // header is finished and there is no listener; there never will be.
        fs::write(
            root.join("Gamelogs/20260915_123126.txt"),
            format!(
                "------------------------------------------------------------\n  Gamelog\n  Session Started: {stamp}\n------------------------------------------------------------\n"
            ),
        )
        .unwrap();
        service.poll(&store, now + 1).unwrap();
        let view = service.view(&store, now + 1).unwrap();
        assert!(view.problems.is_empty(), "{:?}", view.problems);
        assert_eq!(view.sources, 0);

        // A header still being written is a real wait, and says so.
        fs::write(
            root.join("Gamelogs/20260915_123127.txt"),
            "------------------------------------------------------------\n  Gamelog\n",
        )
        .unwrap();
        service.command(&store, Command::Rescan, now + 2).unwrap();
        service.poll(&store, now + 2).unwrap();
        let view = service.view(&store, now + 2).unwrap();
        assert!(
            view.problems.iter().any(|p| p.contains("waiting")),
            "{:?}",
            view.problems
        );
    }

    #[test]
    fn residue_lines_do_not_make_a_healthy_session_look_broken() {
        let (_d, store, mut service, root, now) = setup();
        service
            .command(&store, Command::Start { label: None }, now)
            .unwrap();
        let path = write_log(&root, 9, now + 1, &[(now + 2, false, 100)]);
        let mut text = fs::read_to_string(&path).unwrap();
        text += &format!(
            "[ {} ] (mining) <color=0x77ffffff>Additional <font size=12>40<font size=10> units depleted from asteroid as residue\r\n",
            chrono::DateTime::from_timestamp(now + 2, 0)
                .unwrap()
                .format("%Y.%m.%d %H:%M:%S")
        );
        fs::write(&path, text).unwrap();
        service.poll(&store, now + 3).unwrap();

        let view = service.view(&store, now + 3).unwrap();
        let session = view.session.unwrap();
        assert!(
            (session.totals.total_m3 - 30.0).abs() < 1e-9,
            "residue is not yield"
        );
        assert!(
            !session.coverage_incomplete,
            "a message we understand and exclude is not missing coverage"
        );
        assert!(view.problems.is_empty(), "{:?}", view.problems);
    }

    #[test]
    fn a_retried_new_session_command_is_the_same_session_twice() {
        let (_d, store, mut service, _root, now) = setup();
        service
            .command(&store, Command::Start { label: None }, now)
            .unwrap();
        let retry = Command::New {
            label: Some("Second belt".into()),
            request_id: "shell-retry-1".into(),
        };
        service.command(&store, retry.clone(), now + 10).unwrap();
        let view = service.command(&store, retry, now + 11).unwrap();
        // The retry is absorbed: the first session closed, the second is open,
        // and no third session was created by the repeated command.
        assert_eq!(view.history.len(), 2);
        assert_eq!(view.session.as_ref().unwrap().label, "Second belt");
        assert_eq!(view.session.as_ref().unwrap().start, now + 11);
        assert_eq!(view.history[1].end, Some(now + 11));
    }

    #[test]
    fn unknown_ore_keeps_its_units_until_the_data_catches_up() {
        let (_d, store, mut service, root, now) = setup();
        service
            .command(&store, Command::Start { label: None }, now)
            .unwrap();
        write_ore_log(&root, 7, now + 1, &[(now + 2, false, 50, "Mystery Rock")]);
        service.poll(&store, now + 3).unwrap();

        let session = service.view(&store, now + 3).unwrap().session.unwrap();
        assert_eq!(session.totals.unresolved, 1);
        assert_eq!(session.totals.total_m3, 0.0, "no volume may be invented");
        assert_eq!(session.pilots[0].ores[0].name, "Mystery Rock");
        assert_eq!(session.pilots[0].ores[0].units, 50);

        // A later data update teaches the service the name; reconciliation runs
        // on the next hourly maintenance pass and must be idempotent after it.
        service.volumes.insert(
            "Mystery Rock".to_owned(),
            Volume {
                id: 99_999,
                micro: 500_000,
            },
        );
        service.poll(&store, now + 3610).unwrap();
        let session = service.view(&store, now + 3610).unwrap().session.unwrap();
        assert_eq!(session.totals.unresolved, 0);
        assert!((session.totals.total_m3 - 25.0).abs() < 1e-9);

        service.poll(&store, now + 7300).unwrap();
        let session = service.view(&store, now + 7300).unwrap().session.unwrap();
        assert_eq!(session.totals.unresolved, 0);
        assert!((session.totals.total_m3 - 25.0).abs() < 1e-9);
    }

    #[test]
    fn turning_tracking_off_ends_the_session_it_was_recording() {
        let (_d, store, mut service, root, now) = setup();
        service
            .command(&store, Command::Start { label: None }, now)
            .unwrap();
        write_log(&root, 3, now + 1, &[(now + 2, false, 100)]);
        service.poll(&store, now + 3).unwrap();

        let mut off = service.preferences.clone();
        off.enabled = false;
        let view = service
            .command(
                &store,
                Command::Preferences {
                    value: Box::new(off),
                },
                now + 4,
            )
            .unwrap();
        assert!(!view.armed);
        let session = view.session.unwrap();
        assert_eq!(session.end, Some(now + 5));
        // Ending the session is not deleting it: the yield it recorded stays.
        assert!((session.totals.total_m3 - 30.0).abs() < 1e-9);
    }

    #[test]
    fn a_custom_aggregate_scope_moves_the_summary_but_not_the_roster() {
        let (_d, store, mut service, root, now) = setup();
        service
            .command(&store, Command::Start { label: None }, now)
            .unwrap();
        write_log(&root, 11, now + 1, &[(now + 2, false, 600)]);
        write_log(&root, 22, now + 1, &[(now + 2, false, 400)]);
        service.poll(&store, now + 3).unwrap();

        let mut scoped = service.preferences.clone();
        scoped.aggregate_pilots = vec!["11".to_owned()];
        let view = service
            .command(
                &store,
                Command::Preferences {
                    value: Box::new(scoped),
                },
                now + 4,
            )
            .unwrap();
        let session = view.session.unwrap();
        assert_eq!(session.pilots.len(), 2, "both pilots stay on the roster");
        assert!((session.totals.total_m3 - 180.0).abs() < 1e-9);
        let graphed = session.graph.last().unwrap();
        assert!((graphed.ordinary * 60.0 - 180.0).abs() < 1e-9);
        assert_eq!(
            graphed.pilots.len(),
            2,
            "a narrowed summary still offers every pilot series"
        );
    }

    #[test]
    fn retention_drops_old_detail_and_keeps_what_history_shows() {
        let (_d, store, mut service, root, now) = setup();
        service
            .command(&store, Command::Start { label: None }, now)
            .unwrap();
        write_log(
            &root,
            5,
            now + 1,
            &[(now + 2, false, 100), (now + 2, true, 50)],
        );
        service.poll(&store, now + 3).unwrap();
        service.command(&store, Command::Stop, now + 4).unwrap();

        // Well past the default 30-day retention.
        let later = now + 91 * 86_400;
        service.poll(&store, later).unwrap();
        let view = service.view(&store, later).unwrap();
        let session = view.session.unwrap();
        assert!(!session.detail_available, "old raw events are gone");
        assert!(session.graph.is_empty());
        assert!((session.totals.total_m3 - 45.0).abs() < 1e-9);
        assert_eq!(session.totals.crits, 1);
        assert!((view.history[0].m3 - 45.0).abs() < 1e-9);
    }
}
